F= formula('F⃗ = I ℓ⃗ × B⃗; |F|=IℓB sin θ; f⃗ = F⃗/ℓ',{'F⃗':'total force on the specified straight wire','I':'conventional current','ℓ⃗':'wire vector in current direction','ℓ':'wire length','B⃗':'uniform magnetic flux density','B':'field magnitude','θ':'angle between current direction and field','f⃗':'force per wire length'},{'F⃗':'N','I':'A','ℓ⃗,ℓ':'m','B⃗,B':'T','θ':'rad or stated degrees','f⃗':'N/m'},['Straight wire in uniform field; scalar formula is a magnitude.'])
E=formula('e=−dλ/dt=−N dΦ/dt; λ=NΦ',{'e':'signed induced EMF for the chosen loop orientation','λ':'total linked flux','N':'number of identical linked turns','Φ':'flux through one turn','t':'time'},{'e':'V','λ':'Wb turn','N':'dimensionless turn count','Φ':'Wb','t':'s'},['All N turns link the stated Φ; consistent loop orientation.'])
KT=formula('T=Fb=NBILb=K_t I; K_t=NBLb',{'T':'electromagnetic torque in the depicted maximum-couple geometry','F':'effective force on each active side','b':'separation between active force lines','N':'effective conductor factor used by the source','B':'uniform field magnitude','I':'armature current','L':'active conductor length','K_t':'torque constant'},{'T':'N m','F':'N','b,L':'m','N':'dimensionless','B':'T','I':'A','K_t':'N m/A'},['Constant flux and perpendicular active conductors; do not double-count the two sides of the couple.'])
DC=formula('V_b=K_v ω; V=RI+L_a dI/dt+V_b; T=K_t I; T=(K_t/R)(V−K_v ω) in steady electrical operation',{'V_b':'opposing back EMF','K_v':'back-EMF constant in this lecture, not rpm/V speed constant','ω':'angular speed','V':'applied armature voltage','R':'armature resistance','I':'armature current','L_a':'armature inductance','t':'time','T':'electromagnetic torque','K_t':'torque constant'},{'V,V_b':'V','K_v':'V/(rad/s)','ω':'rad/s','R':'Ω','I':'A','L_a':'H','t':'s','T':'N m','K_t':'N m/A'},['Constant flux; linear circuit; steady relation neglects L_a dI/dt, not the physical existence of inductance.'])
PWR=formula('P_e=VI; P_cu=I²R; P_m=Tω; P_e=P_cu+P_m',{'P_e':'electrical input power','V':'applied voltage','I':'armature current','P_cu':'winding copper loss','R':'armature resistance','P_m':'converted mechanical power','T':'electromagnetic torque','ω':'angular speed'},{'P_e,P_cu,P_m':'W','V':'V','I':'A','R':'Ω','T':'N m','ω':'rad/s'},['Steady ideal motor, K_t=K_v in compatible SI units, no iron/friction/controller losses.'])
PWM=formula('D=t_on/T_s; V_avg=D V_s',{'D':'unipolar PWM duty ratio','t_on':'on time','T_s':'switching period','V_avg':'cycle-average terminal voltage','V_s':'switched supply voltage'},{'D':'dimensionless','t_on,T_s':'s','V_avg,V_s':'V'},['Ideal waveform switches between 0 and V_s; this alone is not a speed law.'])
OP=formula('J dω/dt=T_m(ω)−T_L(ω); equilibrium: T_m=T_L; local stability: d(T_m−T_L)/dω < 0',{'J':'positive lumped rotational inertia','ω':'shaft speed','t':'time','T_m':'motor torque','T_L':'opposing load torque'},{'J':'kg m²','ω':'rad/s','t':'s','T_m,T_L':'N m','d(T_m−T_L)/dω':'N m/(rad/s)'},['Added one-state rigid-shaft model; differentiable local curves, no delayed controller or extra dynamics.'])
SYNC=formula('n_s=60 f/p=120 f/P; s=(n_s−n_r)/n_s',{'n_s':'synchronous rotating-field speed','f':'electrical supply frequency','p':'pole-pair count','P':'total pole count, P=2p','n_r':'induction rotor speed','s':'induction slip'},{'n_s,n_r':'rpm','f':'Hz','p,P,s':'dimensionless'},['Balanced rotating field; synchronous rotor locks to n_s; induction formula describes the declared motoring example.'])
STEP=formula('α=360°/N_s; θ=n_c α/m; n_r=60 f_c/(mN_s)',{'α':'nominal full-step angle','N_s':'full steps per revolution','θ':'commanded rotation','n_c':'command pulse count','m':'microsteps per full step','n_r':'nominal shaft speed','f_c':'command pulse frequency'},{'α,θ':'degrees','N_s,n_c,m':'dimensionless counts','n_r':'rpm','f_c':'Hz'},['One commanded increment per pulse, no missed steps; nominal command resolution is not guaranteed mechanical accuracy.'])
# Electromagnetic principles.
a(1688,'force-density','Force versus force per length','The slide writes F⃗ = I⃗ × B⃗ and explicitly defines F as force per unit length. Which interpretation is dimensionally consistent?', [('Use I times a unit direction cross B for N/m; multiply by conductor length for total force.','A tesla times ampere has units N/m.'),('Interpret the same expression as total newtons for any wire length.','That drops the length needed for total force.'),('Interpret the expression as torque in N m without a lever arm.','A torque also needs geometry.'),('Interpret it as electrical power because it contains current.','The magnetic-field factor does not turn it into watts.')], 'The source notation is shorthand for force density; the total-force relation requires the length vector.',loc='First force equation and following force-per-unit-length definition.',kind='equation',forms=[F],conflict='F is written without a length factor while explicitly defined as force per unit length; do not silently treat it as total force.',external=['force'])
a(1688,'force-direction','Cross-product direction','A straight wire carries conventional current in +x and a uniform field points in +y. What is the magnetic-force direction?', [('+z.','The right-handed cross product x×y is z.'),('−z.','This reverses the cross-product order.'),('+y.','The force is not parallel to the applied field.'),('+x.','The force is not parallel to the current.')], 'Current direction crossed with field direction gives +z.',loc='Right-hand-rule figure and vector cross product.',kind='figure',typ='scenario',forms=[F],steps=['x̂ × ŷ = ẑ.'])
a(1688,'force-reversal','Reversing current and field','For nonzero perpendicular current and field, what happens to force when both current and field directions are reversed?', [('It keeps its original direction and magnitude.','Two sign reversals cancel in the cross product.'),('It reverses direction but keeps magnitude.','That occurs when only one factor reverses.'),('It doubles in magnitude without changing direction.','No magnitude was changed.'),('It vanishes because the two reversals cancel the field.','Reversing directions does not remove either vector.')], 'The product of two negative signs leaves the force unchanged.',loc='F vector cross-product law.',kind='equation',forms=[F])
a(1688,'stationary-wire','Current without bulk translation','Which qualification is needed for the sentence saying a current-carrying conductor “is moved” in a magnetic field?', [('The conductor can be stationary as a body; drift of charge already constitutes current and permits magnetic force.','Bulk motion is not required for the current-force law.'),('The entire conductor must translate at the same speed as its charge carriers.','Carrier drift and bulk wire motion are different.'),('A stationary wire experiences force only if its current is zero.','Zero current removes this force contribution.'),('A stationary current-carrying wire must have a force parallel to B.','The magnetic force is transverse to current and field.')], 'The source wording should not turn wire translation into a necessary condition.',loc='Opening current-carrying conductor sentence.',conflict='The wording suggests bulk conductor motion is necessary for force.',external=['force'])
a(1689,'wire-force','Wire-force calculation','A 0.20 m wire carries 3 A at 30° to a uniform 0.50 T field. What is its total magnetic-force magnitude?', [('0.15 N.','Include the sine of 30 degrees.'),('0.30 N.','This assumes perpendicular orientation.'),('0.75 N.','This omits the specified wire length.'),('0.60 N.','This divides by sin 30 degrees instead of multiplying.')], 'The printed F=BIL is the perpendicular special case; the supplied angle requires the general form.',loc='F=BIL equation and length-L conductor figure.',kind='equation',typ='numerical',steps=['F=0.50×3×0.20×sin30°=0.15 N.'],forms=[F],assumptions=['Added dimensions and angle; uniform field, straight wire.'])
a(1689,'motional-emf','Motion and induced EMF','A straight rod translates parallel to a uniform magnetic field. Under the ideal motional-EMF model, why is translation alone insufficient to imply a nonzero rod EMF?', [('v×B is zero for parallel motion.','There is no transverse magnetic force on charges from this motion.'),('The magnetic field must first be switched off.','Removing B would not create this magnetic motional EMF.'),('Any motion gives the same EMF independent of direction.','The vector product depends on orientation.'),('A rod must carry a pre-existing DC current before any motional EMF can exist.','A motional EMF can exist in an open conductor without a pre-existing current.')], 'The source induction sentence requires suitable flux-cutting geometry, not arbitrary motion.',loc='Sentence linking conductor motion in a magnetic field to induced EMF.',typ='scenario',assumptions=['Added ideal rod model e=∫(v×B)·dℓ; parallel v and B.'])
a(1690,'lenz','Lenz-law wording','What does the minus sign in Faraday’s law express, correcting the slide’s phrase “oppose the charge producing it”?', [('The induced response opposes the change in linked magnetic flux.','The following paragraph correctly identifies flux change.'),('The response always opposes the existing magnetic flux, even when it is decreasing.','For decreasing flux it acts to maintain the original flux.'),('The induced voltage is negative in every possible reference orientation.','Its algebraic sign depends on the chosen orientation.'),('The response removes the electric charge that made the field.','Lenz law is not charge destruction.')], 'The local “charge” wording is a typo for change; preserve the distinction and reference orientation.',loc='e=−dφ/dt equation, charge wording and next flux-change paragraph.',kind='equation',forms=[E],conflict='The source says charge where its own following explanation requires change in flux.',external=['faraday'])
a(1690,'faraday-turns','Linked-flux calculation','A 100-turn coil has identical flux per turn rising uniformly from 1 mWb to 3 mWb in 20 ms. Using the stated positive flux orientation, what is the average induced EMF?', [('−10 V.','The 100 turns multiply the per-turn rate.'),('−0.10 V.','This is the one-turn result.'),('+10 V.','This omits the minus sign for the stated orientation.'),('−15 V.','This divides the final flux by time rather than using its change.')], 'Use change in flux, not final flux, and distinguish per-turn flux from flux linkage.',loc='Faraday equation and time-rate-of-flux explanation.',kind='equation',typ='numerical',steps=['ΔΦ=(3−1)×10⁻³=0.002 Wb.','e=−100×0.002/0.020=−10 V.'],forms=[E],assumptions=['Added coil with all turns linking the same flux; uniform change.'])
a(1690,'constant-flux','Flux versus rate','A coil links a large but time-constant flux and has no changing geometry. What EMF follows from the displayed Faraday law?', [('Zero induced EMF.','Its linked-flux derivative is zero.'),('A large constant EMF proportional only to the flux magnitude.','The law depends on its derivative.'),('An EMF that grows linearly with time.','No increasing flux rate is supplied.'),('An alternating EMF at a frequency set by the turn count.','Turn count alone does not create oscillation.')], 'A nonzero flux value does not imply a nonzero flux-change rate.',loc='e=−dφ/dt.',kind='equation',forms=[E])
a(1691,'force-couple','Loop force couple','In the rotating-loop drawing, equal upward and downward forces act on separated active sides. Which mechanical result is possible?', [('Zero resultant force with nonzero torque.','Separated opposite forces form a couple.'),('Zero resultant force necessarily means zero torque.','Moment arms matter.'),('The two forces add to a net upward force of twice either magnitude.','Their translational directions oppose.'),('The two forces create only axial tension with no rotational effect.','Their separated lines of action produce rotation.')], 'A couple can rotate a loop without a net translational force.',loc='Opposite force arrows on the two active loop sides.',kind='figure',typ='diagram')
a(1691,'commutation','Why reverse coil current','Why does the basic DC-loop description reverse coil current as the loop passes the vertical position?', [('To maintain the same sense of electromagnetic torque through successive half-turns.','Current switching prevents the useful torque sense from alternating.'),('To reverse the desired shaft rotation at every half-turn.','That would not provide continuous rotation in one direction.'),('To eliminate the magnetic field throughout the entire rotation.','The field is needed to produce torque.'),('To keep each conductor current permanently unchanged relative to its coil.','Commutation specifically changes that current direction.')], 'Commutation coordinates electrical reversal with rotor position.',loc='Current-reversal sentence and loop sequence.')
a(1692,'commutator-brush','Brush and commutator roles','Which mapping matches the brushed motor construction?', [('Stationary carbon brushes contact rotating segmented commutator connections to the armature coils.','This is the source contact arrangement.'),('Rotating brushes contact a stationary unsegmented slip ring to switch stator poles.','That is not the depicted segmented commutation arrangement.'),('The armature is the stationary field frame and the commutator is the magnetic rotor core.','This confuses coil-bearing rotor and switching contacts.'),('Field poles are the segmented electrical contacts and brushes are the rotor conductors.','Magnetic poles and electrical contacts are distinct.')], 'The commutator supplies position-dependent connection changes while brushes provide external contact.',loc='Armature, segmented ring and carbon brush construction bullets.')
a(1692,'four-pole','Field-pole diagram','In the four-pole construction figure, what do the small conductors around the central magnetic cylinder belong to?', [('The armature rotor.','They are labelled armature conductors.'),('The stationary carbon brushes.','Brushes are contact elements, not all the distributed slot conductors.'),('The external field-supply resistor.','The circle of conductors is inside the armature.'),('The commutator insulation segments alone.','The label identifies current-carrying armature conductors.')], 'Read the actual field-pole and armature labels separately.',loc='Four-pole cross-section, armature conductors and armature labels.',kind='figure',typ='diagram')
a(1692,'reverse-one','Field and armature reversal','For T proportional to field flux times armature current, which operation reverses torque while keeping magnitudes fixed?', [('Reverse armature current only, leaving field direction unchanged.','Exactly one sign changes.'),('Reverse both field and armature current.','Their product keeps its sign.'),('Reverse neither but double both magnitudes.','That changes magnitude, not sign.'),('Exchange two mechanical labels without changing currents or field.','Labels do not change the electromagnetic torque.')], 'Reversing either one electrical factor reverses torque; reversing both does not.',loc='Final direction-reversal statement.',typ='scenario',assumptions=['Declared linear torque T∝ΦI_a model.'])
# Constant-flux DC model and its limits.
a(1693,'couple-arm','Couple-arm geometry','The two equal opposite active-side forces are separated by b. Why is their torque Fb rather than 2Fb about the midpoint?', [('Each force has lever arm b/2, so the two moments sum to Fb.','This uses the stated full separation.'),('Only one force contributes and the other is ignored.','Both forces contribute equally.'),('Each force acts through the full separation b about the midpoint.','That double-counts the lever arm.'),('The torques cancel because the forces point in opposite directions.','Opposite forces on opposite sides have the same moment sense.')], 'The source couple formula already includes both sides.',loc='Loop figure with side separation b and T=Fb.',kind='figure',typ='diagram',forms=[KT])
a(1693,'torque-geometry','Geometric motor constant','Using the slide’s effective N convention, take N=20, B=0.4 T, L=0.10 m and b=0.05 m. At I=2 A, which pair gives K_t and T?', [('0.04 N m/A and 0.08 N m.','Compute NBLb, then multiply by current.'),('0.08 N m/A and 0.16 N m.','This counts the force couple twice.'),('0.4 N m/A and 0.8 N m.','This is ten times the specified geometry product.'),('0.04 N m/A and 0.02 N m.','This divides the constant by current.')], 'The source’s geometric coefficient is evaluated under its effective-count convention.',loc='T=NBILb=Kt I and Kt=NBLb.',kind='equation',typ='numerical',steps=['K_t=20×0.4×0.10×0.05=0.04 N m/A.','T=0.04×2=0.08 N m.'],forms=[KT],assumptions=['Added dimensions; source effective N; perpendicular active segments and constant field.'])
a(1693,'back-emf-constant','Meaning of K_v','The lecture writes V_b=K_vω with ω in rad/s. Which units must K_v have?', [('V/(rad/s).','Multiplying by speed gives volts.'),('rpm/V.','That is a speed-per-voltage convention, inverse to the one used here after unit conversion.'),('N m/A.','These units name a torque constant; numerical SI equivalence needs compatible physical conventions, not a unit substitution.'),('Ω.','Resistance multiplies current, not angular speed, to give voltage.')], 'Do not import a hobby-motor rpm/V convention into this back-EMF equation.',loc='Vb=Kvω and back-EMF coefficient sentence.',kind='equation',forms=[DC],external=['motor'])
a(1693,'back-emf-value','Back-EMF value','For K_v=0.10 V/(rad/s) and ω=100 rad/s, what is V_b?', [('10 V.','Multiply the coefficient by angular speed.'),('1000 V.','This divides speed by the coefficient.'),('0.001 V.','This divides the coefficient by speed.'),('100 V.','This omits the 0.10 coefficient.')], 'This is the source linear back-EMF law with supplied compatible units.',loc='Vb=Kvω.',kind='equation',typ='numerical',steps=['V_b=0.10×100=10 V.'],forms=[DC],assumptions=['Added coefficient and speed; constant-flux model.'])
a(1694,'circuit-steady','Loaded DC current and torque','At steady electrical operation, V=24 V, R=2 Ω, K_v=0.10 V/(rad/s), K_t=0.10 N m/A and ω=100 rad/s. What are I and electromagnetic torque?', [('7 A and 0.70 N m.','Subtract 10 V back EMF before dividing by resistance.'),('12 A and 1.20 N m.','This neglects the nonzero back EMF.'),('17 A and 1.70 N m.','This adds back EMF to supply voltage.'),('5 A and 0.50 N m.','This treats back EMF itself as the resistor voltage.')], 'Only V−V_b drives the resistive voltage drop in this model.',loc='I=(V−Kvω)/R and torque equation.',kind='equation',typ='numerical',steps=['V_b=0.10×100=10 V.','I=(24−10)/2=7 A.','T=0.10×7=0.70 N m.'],forms=[DC],assumptions=['Added constants; steady current, no saturation.'])
a(1694,'stall-free','Stall and ideal free speed','For V=24 V, R=2 Ω, K_t=K_v=0.10 in compatible SI units, what are the quasi-steady stall torque and ideal lossless no-load speed?', [('1.2 N m and 240 rad/s.','Use ω=0 for stall and I=0 for ideal no-load.'),('0 N m and 240 rad/s.','Stall speed zero does not imply zero torque.'),('1.2 N m and 120 rad/s.','Half free speed is not the no-load intercept.'),('2.4 N m and 24 rad/s.','This misses resistance in stall torque and the back-EMF constant in speed.')], 'The intercepts belong to the ideal torque–speed line, not continuous thermal operating permissions.',loc='Starting/no-load discussion and torque-speed line.',kind='equation',typ='numerical',steps=['T_stall=K_t V/R=0.10×24/2=1.2 N m.','ω_0=V/K_v=240 rad/s.'],forms=[DC],assumptions=['Added constants; ignore friction and iron loss; stall arithmetic is not a hardware experiment.'])
a(1694,'voltage-curves','Voltage-shifted torque-speed lines','The source plots V₂>V₁ for an otherwise unchanged constant-flux motor. What changes in the ideal torque–speed relation?', [('Torque and speed intercepts increase while the slope remains −K_tK_v/R.','Voltage changes the intercept, not fixed motor coefficients.'),('The slope changes sign while both intercepts stay fixed.','The negative speed dependence remains.'),('Only the zero-torque intercept decreases.','Higher voltage increases ideal free speed.'),('The curve becomes horizontal because current no longer depends on speed.','Back EMF still reduces current with speed.')], 'The parallel source lines follow directly from the linear equation.',loc='Two torque-speed lines labelled V2>V1 and torque equation.',kind='figure',typ='diagram',forms=[DC])
a(1694,'no-load-loss','Real no-load torque','Why is the slide’s “no load, T=0” condition an idealization?', [('A real freely running shaft can still need electromagnetic torque/current to overcome internal losses.','No external load does not remove friction or iron losses.'),('No external load forces the shaft to be stalled.','No-load and stall are different operating states.'),('Back EMF must be zero whenever there is no external load.','A spinning motor develops back EMF.'),('Real no-load current must equal the stall current.','Those are generally very different states.')], 'The ideal line uses zero internal loss; manufacturer no-load current reflects loss torque.',loc='No-load T=0 statement.',conflict='Zero electromagnetic torque is stated for no load without distinguishing external load from internal losses.',external=['motor'])
a(1694,'inductance-initial','Initial current slope','The source circuit includes armature inductance. With shaft clamped at rest, I(0)=0, V=12 V, R=2 Ω and L_a=20 mH, what is dI/dt at t=0⁺?', [('600 A/s.','Initially RI and back EMF are zero, so V/L_a gives the slope.'),('6 A/s.','6 A is the eventual steady current, not the initial slope.'),('0 A/s.','Current is continuous, but its derivative need not be zero.'),('240 A/s.','Multiplying voltage by inductance gives the wrong dependence and units.')], 'Retaining the depicted inductor prevents an instantaneous current jump.',loc='R,L,Vb series circuit and explicit neglect-of-L approximation.',kind='figure',typ='numerical',steps=['L_a=0.020 H.','dI/dt=(12−2×0−0)/0.020=600 A/s.'],forms=[DC],assumptions=['Added clamped-rotor voltage-step model; ideal constant inductance.'])
a(1694,'electrical-transient','Electrical time constant','For the same clamped-rotor model V=12 V, R=2 Ω, L_a=20 mH and I(0)=0, what current flows after one electrical time constant?', [('About 3.79 A at 10 ms.','τ_e=L_a/R and I=(V/R)(1−e⁻¹).'),('6 A at 10 ms.','This replaces one time constant by the final steady value.'),('About 2.21 A at 10 ms.','This is the remaining gap 6e⁻¹, not current attained.'),('About 3.79 A at 40 ms.','This multiplies L_a by R instead of dividing.')], 'This is a declared derivation from the source circuit, not a printed waveform.',loc='Series R,L and back-EMF equivalent circuit.',kind='figure',typ='numerical',diff='medium',steps=['τ_e=0.020/2=0.010 s.','I(τ_e)=6(1−exp(−1))≈3.7927 A.'],forms=[DC,formula('τ_e=L_a/R; I(t)=(V/R)(1−exp(−t/τ_e))',{'τ_e':'electrical time constant','L_a':'armature inductance','R':'armature resistance','I':'current','V':'constant applied step voltage','t':'elapsed time'},{'τ_e,t':'s','L_a':'H','R':'Ω','I':'A','V':'V'},['Clamped zero-speed rotor; initial current zero; constant R,L_a,V.'])],assumptions=['Added clamped-rotor model; no mechanical acceleration.'])
a(1694,'power-balance','Electromechanical power balance','Use V=24 V, R=2 Ω, I=7 A, ω=100 rad/s and K_t=K_v=0.10 in compatible SI units. What are converted mechanical power and copper loss?', [('70 W and 98 W.','T=0.7 N m and I²R=98 W; their sum is 168 W input.'),('168 W and 98 W.','168 W is electrical input, not converted mechanical output.'),('70 W and 14 W.','14 V is the resistive drop, not watts.'),('98 W and 70 W.','This exchanges copper loss and mechanical power.')], 'The simple model conserves power when the constants use compatible SI conventions.',loc='Constant-flux torque equation and resistor/back-EMF circuit.',kind='equation',typ='numerical',diff='medium',steps=['T=0.1×7=0.7 N m; P_m=0.7×100=70 W.','P_cu=7²×2=98 W.','VI=24×7=168=70+98 W.'],forms=[DC,PWR],assumptions=['Added ideal steady model; no other losses or energy accumulation.'])
a(1694,'maximum-power','Maximum ideal converted power','For the ideal torque line T=1.2−0.005ω in SI units over 0≤ω≤240 rad/s, where is converted mechanical power largest?', [('At 120 rad/s, with 72 W.','The parabola 1.2ω−0.005ω² peaks at half free speed.'),('At stall, with 288 W.','Mechanical power is zero at zero speed.'),('At 240 rad/s, with 288 W.','Torque and converted power vanish at ideal free speed.'),('At 60 rad/s, with 72 W.','At 60 rad/s the power is 54 W, not the maximum.')], 'Maximizing this ideal output-power curve is not the same as maximizing efficiency or respecting a continuous rating.',loc='Linear torque-speed characteristic.',kind='figure',typ='derivation',diff='medium',steps=['P_m=ωT=1.2ω−0.005ω².','dP_m/dω=1.2−0.010ω=0 gives ω=120.','T=0.6 N m, so P_m=72 W; negative second derivative confirms a maximum.'],forms=[PWR],assumptions=['Added numeric torque line and feasible mathematical interval; thermal limits ignored.'])
# Wound-field connections and source conflicts.
a(1695,'series-connection','Series current path','What is characteristic of the stated series-wound DC connection?', [('Field and armature carry the same series current.','They share one path.'),('The field and armature each necessarily receive the full supply across separate parallel branches.','That describes a shunt arrangement.'),('The field current is identically zero because the field is a permanent magnet.','The source specifies a wound series field.'),('The armature is open-circuit while only the field carries current.','That would not be the operating series path.')], 'Series describes the electrical field/armature connection.',loc='Series field-armature circuit.',kind='figure',typ='diagram')
a(1695,'series-polarity','Series supply reversal','Why does reversing both supply terminals of the ideal unsaturated series motor not by itself reverse its electromagnetic torque?', [('Armature current and field flux both reverse, preserving their product.','Both sign factors reverse together.'),('Only the field reverses while armature current stays unchanged.','The shared series path reverses both.'),('Only armature current reverses while field flux stays unchanged.','A wound series field follows its current.'),('Both currents become zero permanently after any polarity change.','Polarity reversal does not imply an open circuit.')], 'To reverse torque, one winding connection must be reversed relative to the other.',loc='Series reversing-polarity statement.',typ='scenario')
SER=formula('Φ=k_f I_a; T=k Φ I_a=k k_f I_a²',{'Φ':'field flux in the declared unsaturated series model','k_f':'flux per series current','I_a':'armature and series-field current','k':'torque coefficient per flux-current product','T':'torque magnitude for fixed relative winding sense'},{'Φ':'Wb','k_f':'Wb/A','I_a':'A','k':'N m/(Wb A)','T':'N m'},['Linear unsaturated series field, fixed relative winding sense; not valid through magnetic saturation.'])
a(1695,'series-square','Series torque scaling','Assume an unsaturated series motor has Φ proportional to current and T proportional to ΦI. If current rises from 2 A to 3 A, by what factor does torque rise?', [('2.25.','Square the current ratio 3/2.'),('1.5.','This uses only one of the two current factors.'),('3.0.','The torque factor is not the new current value.'),('0.444.','This is the reciprocal squared ratio.')], 'This explicitly declared physical derivation is distinct from the source’s uncalibrated current–torque sketch.',loc='Series connection and right-hand current-versus-torque sketch.',kind='figure',typ='numerical',steps=['T_2/T_1=(3/2)²=2.25.'],forms=[SER],assumptions=['Added unsaturated linear-flux model; same relative winding polarity.'],conflict='The drawn current-versus-torque curve is convex upward, unlike I∝sqrt(T) in the stated unsaturated model.')
a(1695,'series-overspeed','Series no-load caution','Which design conclusion follows from the slide’s high no-load-speed warning?', [('A series drive needs appropriate loading/speed protection rather than assuming unloaded running is harmless.','Weak field at small load current can require high speed for back EMF.'),('Removing load makes the speed automatically settle to zero.','The warning is about high speed, not guaranteed stopping.'),('The no-load speed equals the stall speed by definition.','Stall is zero shaft speed.'),('A high starting torque establishes the continuous safe speed limit.','Starting torque and overspeed constraints are different ratings.')], 'This is a theoretical selection warning, not an instruction to run a motor unloaded.',loc='High starting torque and greater no-load speed bullets.',typ='scenario')
a(1696,'shunt-topology','Shunt topology qualification','The slide’s prose calls the field parallel with the armature. Which circuit is consistent with that definition, rather than the sketch’s common Ra/La placement?', [('A field branch across the supply and a separate armature branch containing its resistance, inductance and back EMF.','Each complete branch spans the supply.'),('Armature resistance and inductance in the only common supply path before the field splits off.','Then field current also passes through elements labelled armature.'),('The field winding in series with the entire armature and no parallel branch.','That is a series connection.'),('A field branch disconnected at both ends while the armature operates.','That is not an energized shunt field.')], 'Use the explicit parallel-winding definition and retain the drawn topology mismatch as a local source issue.',loc='Parallel-field prose and Ra/La/LF/RF/Vb circuit.',kind='figure',typ='diagram',conflict='The source sketch places Ra/La in a common path before the field branch, inconsistent with the ordinary armature/field parallel definition.')
a(1696,'shunt-current','Shunt line-current calculation','For a declared correct shunt connection across 24 V, field resistance is 120 Ω and the armature has R_a=2 Ω and back EMF 20 V. What is the supply line current?', [('2.2 A.','Add 0.2 A field current to 2 A armature current.'),('2.0 A.','This omits field current.'),('0.2 A.','This omits armature current.'),('12.2 A.','This omits armature back EMF.')], 'The exercise explicitly uses independent parallel branches, not the misdrawn shared-armature-resistance sketch.',loc='Shunt parallel-field statement and circuit.',kind='figure',typ='numerical',diff='medium',steps=['I_f=24/120=0.2 A.','I_a=(24−20)/2=2 A.','I_line=I_f+I_a=2.2 A.'],forms=[DC,formula('I_f=V/R_f; I_line=I_f+I_a',{'I_f':'shunt field current','V':'common branch voltage','R_f':'field resistance','I_line':'total supply current','I_a':'armature branch current'},{'I_f,I_line,I_a':'A','V':'V','R_f':'Ω'},['Correct parallel branches; steady electrical operation.'])],assumptions=['Added numeric correct shunt circuit; no transient field current.'],conflict='The exercise corrects the source sketch topology explicitly, using the stated parallel-winding definition.')
a(1696,'shunt-regulation','Shunt speed regulation','Which interpretation of good shunt speed regulation is appropriate under constant voltage and approximately constant field flux?', [('Speed changes relatively little with load, but armature resistive drop can still reduce it.','Good regulation is not exact load independence.'),('Speed is mathematically fixed for every load up to an unlimited torque.','The source does not remove losses or ratings.'),('Armature current remains constant even as required torque changes.','At constant flux, torque requires current change.'),('The field must reverse direction each time load increases.','Load regulation does not require reversing field polarity.')], 'The near-flat qualitative curve is an approximation within operating limits.',loc='Speed-regulation bullets and torque-speed plot.',kind='figure',typ='scenario',forms=[DC])
a(1696,'shunt-linearity','Current-torque curve qualification','At fixed field flux, which dependence follows from T=K_t I_a despite the curved current–torque sketch?', [('I_a is proportional to T.','Solve I_a=T/K_t for constant K_t.'),('I_a is proportional to T².','That squares the relation without a model basis.'),('I_a is inversely proportional to T.','The constant-flux torque law is direct.'),('I_a is independent of T.','A varying electromagnetic torque requires varying current.')], 'Use the declared fixed-flux equation, not a quantitative reading of the uncalibrated sketch.',loc='Right-hand current-versus-torque sketch and shunt field description.',kind='figure',forms=[DC],conflict='The displayed nonlinear current-versus-torque curve conflicts with the constant-field linear torque-current model.')
a(1697,'compound-conflict','Conflicting compound ranking','Which statement accurately reports the slide’s internal starting-torque inconsistency?', [('The prose calls compound starting torque highest, while the table labels it average.','Both descriptions occur on the same page.'),('Both prose and table label compound starting torque highest.','The table says average.'),('The prose says compound torque is zero and the table says negative.','Neither description appears.'),('The table labels series starting torque average and shunt starting torque high.','The displayed series/shunt entries are high/average.')], 'Do not silently choose a universal ranking from contradictory source entries; use actual motor/design data for selection.',loc='Compound starting-torque bullet and Starting torque table row.',kind='table',conflict='Compound starting torque is highest in prose and average in the table.')
a(1697,'field-resistance','Source comparison table','According to the displayed field-resistance row, which mapping is correct?', [('Shunt high; series low; compound parallel field high and series field low.','This is the table mapping.'),('Shunt low; series high; both compound fields low.','This reverses the shunt/series entries.'),('All three field windings have the same listed resistance.','The table distinguishes them.'),('Shunt and series have no field resistance because both are permanent-magnet motors.','These are wound-field categories.')], 'This is a source-table comparison, not a numerical resistance specification.',loc='Field resistance row, columns Shunt/Series/Compound.',kind='table',typ='match')
a(1697,'compound-construction','Compound winding combination','What makes the stated motor compound-wound?', [('It combines a shunt field winding and a series field winding.','Both excitation paths are present.'),('It contains two armatures but no field winding.','That is not the definition.'),('It is simply a permanent magnet with one unconnected coil.','The source specifies wound-field combinations.'),('It replaces the armature with a squirrel cage supplied by single-phase AC.','That is a different motor category.')], 'The connection type is separate from the source’s inconsistent performance ranking.',loc='Opening compound-field description.')
a(1698,'pm-cutaway','PM does not mean brushless','Which labelled components in the PM motor cutaway demonstrate that this particular permanent-magnet motor is brushed?', [('Brush and commutator.','Those are mechanical current-switching contacts.'),('Encoder and output shaft.','These do not determine commutation type.'),('Magnet and reduction gearhead.','Both can appear in brushed or brushless drives.'),('Ironless winding and encoder.','Core construction and position measurement do not establish brushlessness.')], 'Permanent magnet describes the field source, not whether commutation uses brushes.',loc='Cutaway labels Brush, Commutator, Magnet, Ironless winding, Encoder and Reduction gearhead.',kind='figure',typ='diagram')
a(1698,'pm-loss','Permanent-magnet excitation','Which loss is specifically avoided by using permanent magnets instead of an electrically excited field winding?', [('Field-winding excitation copper loss.','No field current is needed to create the PM field.'),('All armature copper loss.','Torque-producing winding current still dissipates I²R.'),('All bearing and brush friction.','A PM design can still have bearings and brushes.'),('Every loss in the external motor controller.','The field choice does not eliminate controller dissipation.')], 'No field excitation power is not a claim of lossless conversion.',loc='Permanent-field and efficiency advantages.')
a(1698,'gearhead','Gearhead torque-speed tradeoff','For an added ideal 10:1 speed-reduction gearhead on the pictured motor, input speed is 100 rad/s and input torque is 0.20 N m. What are output speed and torque?', [('10 rad/s and 2.0 N m.','Ideal reduction trades speed for torque at equal power.'),('1000 rad/s and 2.0 N m.','Both increases would violate the ideal power balance.'),('10 rad/s and 0.02 N m.','This reduces both speed and torque.'),('1000 rad/s and 0.02 N m.','That is a speed-increasing ratio, not the declared reduction.')], 'The numeric ratio is added; the source only identifies a reduction gearhead.',loc='Reduction gearhead and output-shaft labels in PM cutaway.',kind='figure',typ='numerical',steps=['ω_out=100/10=10 rad/s.','T_out=10×0.20=2.0 N m; both sides have 20 W.'],forms=[formula('ω_out=ω_in/g; T_out=η_g g T_in',{'ω_out,ω_in':'output and input angular speeds','g':'input/output speed ratio','T_out,T_in':'output and input torque','η_g':'gear efficiency'},{'ω_out,ω_in':'rad/s','g,η_g':'dimensionless','T_out,T_in':'N m'},['Added constant-ratio model; η_g=1 here.'])],assumptions=['Added ideal ratio, no gear losses.'])
a(1699,'pwm-average','PWM average voltage','An ideal unipolar PWM waveform switches between 0 and 24 V, with 30 μs on in every 50 μs period. What is its average voltage?', [('14.4 V.','Duty is 30/50=0.6.'),('9.6 V.','This uses the off-time fraction.'),('24 V.','This uses peak rather than average voltage.'),('40 V.','This divides supply by duty instead of multiplying.')], 'The source pulse-width control is converted into an explicitly ideal average-voltage calculation.',loc='Motor-voltage PWM pulse diagram.',kind='figure',typ='numerical',steps=['D=30/50=0.6.','V_avg=0.6×24=14.4 V.'],forms=[PWM],assumptions=['Added two-level ideal waveform; no switching voltage losses.'])
a(1699,'pwm-frequency','Duty and carrier frequency','If PWM frequency doubles but duty remains 60% for the same ideal 0/24 V waveform, what happens to average applied voltage?', [('It remains 14.4 V.','The time fraction at 24 V remains 0.6.'),('It doubles to 28.8 V.','Frequency alone does not double the time fraction.'),('It halves to 7.2 V.','The on time and period both halve.'),('It becomes zero because the period is shorter.','The positive pulse area per unit time remains unchanged.')], 'Ripple and switching losses can change, but the specified ideal average does not.',loc='Fixed-supply PWM waveform and pulse-width-control statement.',kind='figure',typ='scenario',forms=[PWM])
a(1699,'current-speed','Current is not a complete speed law','Why is “PM speed depends on armature current” incomplete as a speed-control rule?', [('Current sets torque in the constant-flux model, while speed also follows voltage, back EMF and load balance.','All these relations must be compatible.'),('Current determines only rotor position and has no relation to torque.','The preceding slide explicitly gives T=K_t I.'),('A fixed current implies the same speed for every mechanical load and supply voltage.','This ignores electrical and mechanical constraints.'),('Back EMF is independent of speed once permanent magnets are used.','Permanent flux gives the linear speed dependence.')], 'Current control and speed control are related but not identical tasks.',loc='Opening PM speed/armature-current sentence.',conflict='The prose compresses speed control into an armature-current dependence without its voltage/back-EMF/load context.',forms=[DC])
# Direction switching and feedback diagrams.
a(1700,'bridge-diagonals','H-bridge diagonal pairs','In the labelled H bridge, which pair of conducting switch sets produces opposite motor-voltage polarities?', [('S1 with S4, versus S2 with S3.','These are the two opposite diagonals.'),('S1 with S3, versus S2 with S4.','These are same-leg rail short paths, not the intended motor paths.'),('S1 with S2, versus S3 with S4.','These connect both motor terminals toward the same rail, not the two driven polarities.'),('S1 with S4, versus S1 with S4 again.','The unchanged pair cannot reverse the applied polarity.')], 'Switch labels must be read from this actual drawing rather than assumed from another convention.',loc='Four-switch H bridge: S1 upper left, S2 upper right, S3 lower left, S4 lower right.',kind='figure',typ='diagram')
a(1700,'bridge-short','Same-leg bridge state','Why is simultaneously closing S1 and S3 in the source H bridge an invalid driven state?', [('It connects the positive and negative rails through the same left leg.','This is a shoot-through path independent of the intended motor load.'),('It applies a clean reverse voltage through the motor.','The intended reverse diagonal is S2/S3.'),('It safely leaves all motor current paths open.','Both switches are conducting in one rail-to-rail path.'),('It changes only PWM frequency without affecting current paths.','The conducting topology changes directly.')], 'Complementary switching needs appropriate interlocking; this is circuit analysis, not physical wiring guidance.',loc='S1/S3 left bridge leg and supply rails.',kind='figure',typ='diagram')
a(1700,'freewheel','Why freewheel paths matter','What role do the diodes around the motor bridge serve when switching an inductive winding current?', [('They provide permitted recirculation/clamping paths for current that cannot change instantaneously.','Inductance stores energy and enforces current continuity.'),('They force winding current to vanish instantly without energy transfer.','Inductor current cannot generally make that jump.'),('They convert the motor into a permanent short between supply rails in every switch state.','They conduct only under appropriate polarity conditions.'),('They alone determine shaft position without a sensor or motor model.','Their role is an electrical current path, not position measurement.')], 'A simplified bridge drawing is not a complete drive or protection design.',loc='Diodes across H-bridge switching devices.',kind='figure',typ='diagram')
a(1700,'ab-drive','Source A/B direction commands','In the source transistor example, A high/B low and A low/B high are used for what purpose?', [('Selecting opposite diagonal drive paths and opposite rotation commands.','The source assigns these complementary inputs to reversal.'),('Selecting the same diagonal with two different labels.','The active path changes.'),('Measuring absolute shaft angle without any encoder.','A/B here are drive commands, not encoder channels.'),('Changing a DC motor into a single-phase induction motor.','The control logic does not change the motor construction.')], 'The label meanings are local to this source drive circuit; they are not quadrature encoder A/B channels.',loc='Lower transistor bridge and A/B high-low direction statements.',kind='figure',typ='diagram')
a(1701,'tach-path','Tachogenerator feedback conversion','Which signal path is shown for tachogenerator feedback to the digital controller?', [('Motor speed → tachogenerator analogue signal → ADC → microprocessor.','The ADC digitizes the analogue feedback.'),('Motor speed → tachogenerator digital pulses → DAC → microprocessor.','This reverses both signal type and conversion direction.'),('Microprocessor → ADC → analogue tachogenerator → motor command.','That is not the feedback direction.'),('Motor speed → encoder code converter → DAC → tachogenerator.','This mixes the two separate feedback examples.')], 'The upper diagram uses an analogue speed transducer and digital control.',loc='Upper feedback loop: tachogenerator, analogue signal, ADC and digital controller.',kind='figure',typ='diagram')
a(1701,'encoder-path','Encoder does not remove forward DAC','Which statement follows from comparing the two complete feedback diagrams?', [('Encoder feedback uses digital code conversion, but the displayed forward command path still contains a DAC and analogue amplifier.','Both forward paths contain those blocks.'),('Replacing the tachogenerator by an encoder removes every DAC in the drawn system.','The forward DAC remains drawn.'),('The encoder feeds its digital output into the upper diagram’s analogue tachogenerator.','They are alternative feedback transducers.'),('The code converter is drawn as a replacement for the motor power amplifier.','It is in the feedback path, not the forward power path.')], 'Digital feedback does not imply every block in the pictured architecture is digital.',loc='Lower encoder/code-converter loop and shared DAC/amplifier forward blocks.',kind='figure',typ='diagram')
a(1701,'tach-numeric','Feedback calibration and speed error','In an added tachogenerator model V_t=0.02ω with V_t in volts and ω in rad/s, a measured 1.6 V is compared with a target 100 rad/s. What is target minus measured speed?', [('20 rad/s.','Measured speed is 1.6/0.02=80 rad/s.'),('98.4 rad/s.','This subtracts volts directly from angular speed.'),('−20 rad/s.','This reverses the defined error sign.'),('5 rad/s.','This is not the calibrated speed difference.')], 'A feedback voltage must first be converted using the declared sensor calibration.',loc='Upper tachogenerator speed-feedback block.',kind='figure',typ='numerical',steps=['ω_meas=1.6/0.02=80 rad/s.','e_ω=100−80=20 rad/s.'],forms=[formula('V_t=K_gω; e_ω=ω_ref−V_t/K_g',{'V_t':'tachogenerator measured voltage','K_g':'tachogenerator sensitivity','ω':'shaft speed','ω_ref':'target speed','e_ω':'target minus measured speed'},{'V_t':'V','K_g':'V/(rad/s)','ω,ω_ref,e_ω':'rad/s'},['Added ideal linear calibration, no ADC quantization or offset.'])],assumptions=['Added calibration and target; no controller gain or stability claimed.'])
a(1701,'feedback-stability','Feedback is not automatically stable','A designer copies the diagram but increases feedback gain without checking dynamics. Which conclusion is justified?', [('The block diagram alone does not prove stability; gain, plant dynamics and delays still matter.','Closing a loop is not sufficient evidence of stable response.'),('Any negative-feedback connection is stable for every positive gain and delay.','Delay and dynamics can destabilize a nominally negative loop.'),('Using an encoder eliminates all mechanical inertia from the plant.','Sensing does not remove inertia.'),('Adding an ADC ensures the controller has infinite bandwidth.','Sampling and conversion introduce finite timing constraints.')], 'The source supplies architecture, not a complete stability analysis.',loc='Digital controller, conversion blocks, amplifier and motor feedback loops.',kind='figure',typ='scenario')
a(1702,'bldc-construction','BLDC commutation arrangement','Which arrangement matches the BLDC source figure and description?', [('Stationary switched coils surround a permanent-magnet rotor; electronic switching replaces brush commutation.','The labels distinguish stator coils and PM rotor.'),('A stationary segmented commutator switches current into a rotating set of carbon brushes.','That is not the brushless configuration.'),('A squirrel-cage rotor receives all current through a mechanical commutator.','That combines incompatible descriptions.'),('The permanent magnets are the switched transistor base terminals.','Magnetic rotor poles are not electrical control terminals.')], 'Eliminating brush contacts addresses their wear/sparking, not every possible mechanical loss.',loc='Permanent-magnet rotor and stator-coil labels, brush wear and electronic sequence bullets.',kind='figure',typ='diagram')
a(1702,'sensor-count','Three sensors are one implementation','Which qualification is needed for the slide’s statement that outputs from three sensors provide BLDC commutation?', [('It describes a sensored implementation; sensorless methods can estimate rotor position from electrical signals.','Three physical sensors are not part of every BLDC definition.'),('Every BLDC must have exactly three external optical encoders.','The source does not establish that universal device/type requirement.'),('A sensorless controller never uses any measured electrical quantities.','Sensorless rotor-position estimation can still use voltage/current information.'),('Using fewer position sensors necessarily changes the rotor into a wound armature with brushes.','Sensing choice does not add mechanical commutation.')], 'The controller needs a commutation strategy, which may use measured position or estimation.',loc='Final three-sensor and switching-circuit sentences.',conflict='The illustrated three-sensor implementation is stated without the sensorless alternative.',external=['sensorless'])
# AC induction and synchronous machines.
a(1703,'ac-tree','AC classification tree','Which pair of subclasses appears under both single-phase and polyphase branches?', [('Induction and synchronous.','Both branches divide into those two labels.'),('Series and shunt.','Those are the preceding wound-field DC connection categories.'),('Brushed and commutator-only.','Those are not the two lower boxes.'),('Tachogenerator and encoder.','Those are feedback devices, not the motor branches.')], 'The source associates lower/higher power with the phase branches qualitatively.',loc='Full AC motor → single/polyphase → induction/synchronous tree.',kind='figure',typ='diagram')
a([1703,1706],'frequency-poles','Frequency and pole count','For a synchronous rotating field, what additional motor property must be known besides electrical supply frequency to compute mechanical speed?', [('Pole-pair count.','More pole pairs require more electrical cycles per mechanical revolution.'),('Only the painted housing colour.','It has no role in the speed relationship.'),('Only the number of external bearings.','Bearing count is not the electrical/mechanical cycle ratio.'),('Only the sign convention used for torque units.','Changing unit notation does not determine pole count.')], 'Frequency determines field speed together with pole count; rotor speed in an induction motor also needs slip.',loc={1703:'Final supply-frequency speed-control statement.',1706:'One pole-pair example and one mechanical turn per electrical cycle.'},forms=[SYNC])
a(1704,'transformer','Induction-motor transformer analogy','In the source’s induction-motor analogy, which mapping is correct?', [('Stationary stator as primary, rotating rotor as secondary, with flux crossing an air gap.','This is the stated transformer analogy.'),('Rotating stator as secondary and stationary rotor as primary, with no air gap.','This reverses the parts and removes the specified gap.'),('The mechanical shaft is the primary electrical winding and the bearings are the secondary.','Those are not the electromagnetic winding roles.'),('Both windings must be connected through a brush commutator.','Induction does not require that rotor electrical contact.')], 'This analogy explains rotor power transfer without a direct brush connection in the stated induction machine.',loc='Stationary primary/rotating secondary and air-gap paragraphs.',typ='match')
a([1704,1706],'ac-induction-scope','Not every AC rotor is induction-fed','What qualification resolves the phrase “in AC motors, rotor receives power by induction”?', [('It applies to the induction-motor discussion, not to every AC machine such as the PM synchronous rotor shown later.','The later example provides a different rotor-field construction.'),('It proves that permanent-magnet synchronous rotors need a squirrel cage in every design.','That universal inference does not follow.'),('It means every induction rotor is powered through carbon brushes.','That reverses induction and direct conduction.'),('It excludes electromagnetic torque from any motor using AC.','The source describes AC motor torque, not its impossibility.')], 'Use the heading and machine subtype rather than generalizing an induction mechanism to all AC motors.',loc={1704:'Broad AC rotor-induction sentence under Basic Induction Motor.',1706:'Permanent-magnet rotor opening sentence and diagram.'},conflict='The induction transfer mechanism is phrased as a statement about all AC motors.')
a(1705,'cage-path','Squirrel-cage closed circuits','What closes the electrical paths for the rotor currents described on the single-phase cage slide?', [('Conducting rotor bars joined by end rings.','These form closed rotor circuits without an external connection.'),('Carbon brushes touching a segmented commutator.','The source explicitly says there is no external rotor connection.'),('An encoder disk connected in series with each bar.','The encoder is not part of this construction.'),('An air gap wired as a copper conductor between stator and rotor.','Flux crosses the air gap; it is not a wired electrical bridge.')], 'The bars/end rings and stator excitation have different roles.',loc='Copper/aluminium bars, end rings and no external rotor connection statements.',typ='definition')
a(1705,'single-phase-start','Single-phase starting qualification','For the ideal stationary cage rotor driven only by the depicted single main winding, why is an auxiliary starting arrangement needed?', [('The ideal starting torque has no net preferred direction.','The source describes zero resultant starting torque.'),('No rotor current can ever be induced while the rotor is stationary.','The source states induction and rotor current occur.'),('The supply must first be changed permanently to DC.','That is not the stated auxiliary-start requirement.'),('The rotor bars must be cut open to permit torque.','Closed cage circuits are needed for induced currents.')], 'A complete motor may incorporate a starting arrangement; the statement concerns the basic single-winding configuration.',loc='Final stationary-rotor/net-torque and starting-devices paragraph.',assumptions=['Ideal single main winding, no auxiliary starting winding or shading arrangement.'])
a(1706,'sync-onepair','One-pole-pair speed','For the source’s one-pole-pair synchronous arrangement locked to a 50 Hz field, what is the mechanical speed?', [('3000 rpm.','One turn per cycle gives 50 turns/s, multiplied by 60.'),('1500 rpm.','That corresponds to two pole pairs at 50 Hz.'),('50 rpm.','This confuses revolutions per second with per minute.'),('6000 rpm.','This doubles the one-turn-per-cycle result.')], 'The source explicitly relates one pole pair to one mechanical revolution per supply cycle.',loc='One pair of poles and 360-degree rotation per electrical cycle.',typ='numerical',steps=['n_s=60×50/1=3000 rpm.'],forms=[SYNC],assumptions=['Added 50 Hz, synchronous lock, one pole pair.'])
a([1703,1706],'sync-slip','Synchronous field versus induction rotor','An added four-pole machine has a 50 Hz rotating field. An induction rotor runs at 1440 rpm. What are synchronous speed and slip?', [('1500 rpm and 4%.','Four poles mean two pairs; slip is 60/1500.'),('3000 rpm and 52%.','This treats four poles as one pair.'),('1500 rpm and 96%.','96% is rotor/synchronous speed, not slip.'),('750 rpm and −92%.','This treats four poles as four pairs.')], 'Pole count sets field speed; the difference between rotor and field speed is then normalized by field speed.',loc={1703:'Frequency-based AC speed-control statement.',1706:'Pole-pair/electrical-cycle relationship.'},typ='numerical',diff='medium',steps=['p=P/2=2; n_s=60×50/2=1500 rpm.','s=(1500−1440)/1500=0.04=4%.'],forms=[SYNC],assumptions=['Added standard slip definition and four-pole induction example; this numerical example is not printed on the slide.'])
a(1706,'sync-start','Synchronous startup scope','Which statement properly qualifies the blanket claim that synchronous motors require an external starting mechanism?', [('Bare fixed-frequency starting differs from controlled inverter startup, which can align and accelerate a PM rotor electronically.','A modern drive can implement a startup sequence.'),('Every PMSM must always be hand-spun before its inverter can apply torque.','Controlled startup does not require that universal manual step.'),('Changing drive frequency has no effect on the rotating field.','The field frequency is central to synchronous speed.'),('A controlled start converts permanent magnets permanently into a squirrel cage.','The rotor construction is unchanged.')], 'The source basic-machine statement is not a prohibition on drive-controlled startup.',loc='Final external-starting and not-self-starting sentences.',conflict='The startup statement does not distinguish bare fixed-frequency excitation from a controlled inverter.',external=['startup'])
# Steppers, performance curves, and integrated selection.
a(1707,'pulse-count-rate','Pulse count and pulse rate','For a stepper that follows every commanded step, which mapping is correct?', [('Pulse count determines nominal displacement; pulse rate determines nominal speed.','Count integrates motion and rate describes motion per time.'),('Pulse rate alone determines final displacement and count alone determines speed.','Those roles are exchanged.'),('Pulse count determines only field resistance while rate determines rotor tooth count.','These are construction parameters, not command effects.'),('Pulse count and rate are both unrelated to shaft motion.','The source explicitly uses them to command motion.')], 'The qualification excludes missed-step errors, not the basic commanded relationship.',loc='Pulse number/rate position and speed sentence.')
a(1707,'step-angle-list','Step-angle mapping','Which source step-count/angle pair is correct?', [('144 full steps per revolution and 2.5° per step.','360/144=2.5.'),('72 full steps per revolution and 2.5° per step.','72 corresponds to 5 degrees.'),('180 full steps per revolution and 1.8° per step.','180 corresponds to 2 degrees.'),('24 full steps per revolution and 30° per step.','24 corresponds to 15 degrees.')], 'Every listed pair is tied by the 360-degree full turn.',loc='Full six-value steps/revolution and step-angle list.',typ='match',forms=[STEP])
a(1707,'step-motion','Stepper move and time','A 200-full-step/revolution motor receives 50 full-step pulses at 500 pulses/s, with no missed steps. What are commanded rotation and pulse-train duration?', [('90° and 0.10 s.','Each step is 1.8 degrees and 50/500=0.1 second.'),('180° and 0.10 s.','This doubles the per-step angle.'),('90° and 10 s.','This inverts the count/rate duration calculation.'),('50° and 0.40 s.','This treats pulse count as degrees and uses a whole-turn duration.')], 'The same command specifies position by count and elapsed time by pulse rate.',loc='Pulse count/rate and 200-step/1.8-degree entries.',typ='numerical',diff='medium',steps=['α=360/200=1.8°; θ=50×1.8=90°.','t=50/500=0.10 s.'],forms=[STEP,formula('t=n_c/f_c',{'t':'duration of the specified pulse train','n_c':'command pulse count','f_c':'constant pulse rate'},{'t':'s','n_c':'count','f_c':'Hz'},['No gaps between pulses beyond the specified period.'])],assumptions=['Added command; full-step operation and no missed steps.'])
a(1707,'step-speed','Stepper shaft speed','A 200-full-step/revolution motor follows 500 full-step commands each second. What is shaft speed?', [('150 rpm.','500/200=2.5 turns/s, or 150 per minute.'),('2.5 rpm.','This is the turns-per-second value mislabeled.'),('600 rpm.','This uses 50 instead of 200 steps per revolution.'),('100000 rpm.','Multiplying rate by steps/revolution is the wrong conversion.')], 'Divide command rate by steps per revolution before converting to rpm.',loc='Pulse rate controls speed and 200-step example.',typ='numerical',steps=['n_r=60×500/200=150 rpm.'],forms=[STEP],assumptions=['Added pulse rate; no missed steps, full stepping.'])
a(1707,'pm-stepper-figure','PM stepper winding axes','Which reading matches the PM stepper figure?', [('W1 lies on the left/right stator axis, W2 on the top/bottom axis, and the rotor carries N/S poles.','The two winding pairs and PM rotor are labelled.'),('W1 and W2 are both brushes contacting a commutator disk.','The drawing shows stator windings, not brush contacts.'),('N/S identify the two digital input terminals rather than rotor poles.','They label magnetic rotor polarity.'),('The figure shows an unwound squirrel cage with no stator coils.','Both winding pairs are explicitly drawn.')], 'Read the magnetic rotor and orthogonal winding axes separately.',loc='W1 left/right, W2 top/bottom, N/S rotor and x/y/z axes.',kind='figure',typ='diagram')
a(1708,'reluctance','Variable-reluctance alignment','What produces alignment in the variable-reluctance stepper described?', [('The ferromagnetic rotor moves toward minimum magnetic reluctance under the excited stator field.','That alignment allows greater flux for the excitation.'),('A permanently magnetized rotor must always align a fixed north pole with every north stator pole.','The source specifically contrasts VR with the PM rotor.'),('The rotor bars must be switched through a segmented commutator.','VR alignment does not use that brushed construction.'),('Minimum flux and maximum reluctance are the intended stable positions.','This reverses the stated tendency.')], 'The mechanism is geometry-dependent magnetic reluctance, not mandatory rotor permanent magnetism.',loc='Ferromagnetic rotor and minimum-reluctance/maximum-flux statements.')
a(1708,'phase-teeth','Phase is not tooth count','The VR figure labels stator pairs A/A′, B/B′, C/C′ and D/D′ around a six-tooth rotor. What does “phase” mean in the accompanying specifications?', [('An independently excited stator winding, not one phase per visible rotor tooth.','The definition concerns independent stator windings.'),('One phase for every rotor tooth, so the definition requires six phases.','Rotor tooth count and winding count differ.'),('One phase for every letter occurrence, so every paired pole must be an independent phase.','A/A-prime can be opposite poles of one winding.'),('A phase is the full 360-degree mechanical turn.','That is not the source electrical winding definition.')], 'The eight stator poles and six rotor teeth do not by themselves redefine phase count.',loc='Phase definition and A/A′ through D/D′ VR drawing.',kind='figure',typ='diagram')
a(1708,'vr-step-angle','Geometric VR step inference','In an added ideal reading of the shown four-phase/eight-stator-pole, six-rotor-tooth geometry, adjacent stator axes differ by 45° and rotor teeth by 60°. If the next phase attracts the nearest tooth, what is the smallest nonzero alignment change?', [('15°.','The mismatch between 60-degree tooth spacing and 45-degree stator-axis spacing is 15 degrees.'),('45°.','This assumes the same rotor tooth must travel to the next stator axis.'),('60°.','This uses a full rotor tooth pitch.'),('105°.','This adds the pitches rather than selecting the nearest alignment.')], 'The phase sequence and nearest-tooth assumption are explicitly added; the source does not print this numeric derivation.',loc='VR figure with eight stator poles and six rotor teeth; step-angle definition.',kind='figure',typ='numerical',steps=['Rotor pitch=360/6=60°.','Adjacent stator axis spacing=360/8=45°.','Nearest alignment shift=|60−45|=15°.'],forms=[formula('α=|360°/N_r−360°/N_p|',{'α':'nearest alignment increment for this declared adjacent-phase geometry','N_r':'uniform rotor-tooth count, here 6','N_p':'uniform stator-pole count, here 8'},{'α':'degrees','N_r,N_p':'dimensionless counts'},['Specific 6-tooth/8-pole adjacent-phase example; not a universal formula for every stepper design.'])],assumptions=['Added uniformly spaced ideal geometry and adjacent-phase nearest-tooth selection; no missed steps.'])
a(1708,'holding-torque','Holding versus detent torque','Which interpretation matches the essential holding-torque definition, without the confusing final reversing-spindle clause?', [('The maximum opposing torque sustained by an energized stationary motor before it loses its held position.','Power and stationary position are essential.'),('The same torque rating measured only with all windings unpowered.','That is a different detent-torque condition.'),('The maximum continuous shaft power at its highest speed.','Holding torque is measured at zero speed, not maximum power.'),('The torque required to reverse direction after every normal pulse.','Reversal is not a required part of the holding-torque definition.')], 'Use the powered stationary condition; the source’s extra reversing clause should not become a separate test condition.',loc='Holding torque specification paragraph.',conflict='The definition ends with an ambiguous reversing-spindle clause that is not needed for the stationary holding condition.',external=['holding'])
a(1709,'selection-factors','Selection under duty and reversal','Two candidate motors share the same ideal no-load speed and stall torque. What still has to be checked for a robot requiring repeated reversals and long holding intervals?', [('Continuous/peak capability, duty cycle, thermal limits, reversibility and the actual load-speed requirement.','Two intercepts do not specify the full use case.'),('Only the largest printed stall torque, treating it as continuous at every speed.','Stall and continuous ratings differ.'),('Only unloaded speed, ignoring the torque demand during acceleration.','The loaded trajectory needs torque.'),('Only whether both motors have the same number of housing screws.','That does not establish electromechanical suitability.')], 'The source explicitly lists duty, reversal, starting torque, power and torque-speed range.',loc='Six selection-factor bullets and separate performance curves.',typ='scenario')
a(1709,'peak-continuous','Reading separate performance limits','At about 2000 rpm and 1 N m, the plotted point is above the motor continuous boundary but below the driver peak curve. What can be inferred from the figure alone?', [('Peak capability does not establish continuous suitability at that point.','The operating boundaries are distinct.'),('The point is automatically safe for indefinite operation because it is below the peak curve.','That ignores the lower continuous boundary.'),('The point must have zero mechanical power because it exceeds the continuous boundary.','Power can be nonzero even when continuous operation is disallowed.'),('The driver peak curve is another name for the continuous motor curve.','Both are separately labelled.')], 'Duration, temperature and duty data would be needed before approving a transient operating cycle.',loc='Typical servomotor graph: driver peak torque-speed, motor continuous operation boundary, commutation limit.',kind='figure',typ='diagram')
a(1709,'commutation-limit','Commutation limit versus thermal limit','Why must the figure’s commutation limit not be replaced by the continuous-operation boundary?', [('They describe different constraints; staying under one does not automatically satisfy the other.','The plot labels distinct performance envelopes.'),('Both names necessarily mean the same measured heating curve.','The source draws and labels them separately.'),('A commutation limit applies only at zero speed, never at high speed.','The plotted commutation limit extends into the high-speed region.'),('A continuous boundary applies only to colour coding and has no operating meaning.','It explicitly bounds motor continuous operation.')], 'Motor selection must respect all relevant restrictions, not one preferred curve.',loc='Upper dash-dot Commutation Limit and lower continuous-operation line.',kind='figure',typ='diagram')
a(1710,'intersection','Operating-point meaning','What identifies the operating point in the motor/load diagram?', [('Motor torque equals opposing load torque at the same speed.','The curves intersect there.'),('Motor torque is maximal regardless of load.','The intersection need not be the stall or maximum-torque point.'),('Both motor and load torque must be zero.','The pictured intersection has positive torque.'),('Motor and load speeds are compared at unrelated torque values.','They share one shaft speed and balance torque.')], 'Torque balance is the equilibrium condition in the added positive-inertia shaft model.',loc='Intersection arrow and operating-speed mark.',kind='figure',typ='diagram',forms=[OP])
a([1694,1710],'loaded-point','Integrated loaded operating point','Use the declared motor V=24 V, R=2 Ω, K_t=K_v=0.10 in compatible SI units, with load T_L=0.20+0.005ω N m. At steady state, what are speed and torque?', [('100 rad/s and 0.70 N m.','The motor and load lines intersect at that pair.'),('240 rad/s and 0 N m.','That is the ideal unloaded motor intercept, not the load equilibrium.'),('120 rad/s and 0.60 N m.','This is the motor maximum-power point, not this load intersection.'),('200 rad/s and 0.20 N m.','The specified load at 200 rad/s is 1.2 N m, not 0.2.')], 'Electrical torque and the added speed-dependent load must be solved together.',loc={1694:'T=Kt(V−Kvω)/R.',1710:'Motor/load curve intersection as operating point.'},kind={1694:'equation',1710:'figure'},typ='numerical',diff='medium',steps=['T_m=0.1(24−0.1ω)/2=1.2−0.005ω.','1.2−0.005ω=0.2+0.005ω gives ω=100 rad/s.','T=0.2+0.005×100=0.7 N m.'],forms=[DC,OP],assumptions=['Added linear load; steady ideal fixed-flux motor, no separate friction term.'])
a([1694,1699,1711],'pwm-loaded-point','Duty is not loaded-speed percentage','Use ideal averaged PWM from 24 V and the motor R=2 Ω, K_t=K_v=0.10 SI with load T_L=0.20+0.005ω. Its full-duty equilibrium is 100 rad/s. What equilibrium results at 50% duty?', [('40 rad/s and 0.40 N m.','The 12 V torque line intersects the same load at 40.'),('50 rad/s and 0.45 N m.','Half duty need not give half loaded speed.'),('120 rad/s and 0 N m.','That is the ideal 12 V no-load intercept.'),('100 rad/s and 0.70 N m.','This leaves speed unchanged despite the reduced applied voltage.')], 'The fixed load intercept makes the speed-versus-duty relation nonproportional.',loc={1694:'Constant-flux torque equation.',1699:'PWM applied-voltage waveform.',1711:'Voltage changes the torque-speed characteristic and operating speed.'},kind={1694:'equation',1699:'figure',1711:'statement'},typ='numerical',diff='medium',steps=['V_avg=0.5×24=12 V.','T_m=0.6−0.005ω.','0.6−0.005ω=0.2+0.005ω gives ω=40 rad/s and T=0.4 N m.'],forms=[PWM,DC,OP],assumptions=['Added ideal average-voltage model with small enough ripple for the stated steady approximation; same load.'])
a(1711,'local-response','Restoring acceleration signs','For the depicted declining motor curve and rising load curve, what happens after a small speed disturbance?', [('Below equilibrium it accelerates; above equilibrium it decelerates.','Net torque points back toward the intersection.'),('Below equilibrium it decelerates; above equilibrium it accelerates.','That describes an unstable sign pattern, opposite to the drawing.'),('It accelerates on both sides because motor torque is positive.','Acceleration depends on net torque, not motor torque alone.'),('It stays exactly at the disturbed speed because inertia prohibits acceleration.','Positive inertia relates net torque to acceleration, not a prohibition.')], 'The stated response follows from the relative curves and positive inertia.',loc='Below/above operating-speed bullets and curves.',kind='figure',typ='diagram',forms=[OP])
a(1710,'equilibrium-stability','Not every intersection is stable','In the added model Jω̇=T_m−T_L with J>0, which local slope condition makes a torque-balance point asymptotically stable?', [('d(T_m−T_L)/dω<0 at equilibrium.','An increased speed then creates negative net torque.'),('d(T_m−T_L)/dω>0 at equilibrium.','This reinforces small speed deviations.'),('Any intersection is stable regardless of slopes.','Torque equality alone establishes equilibrium, not stability.'),('Motor torque must be zero at equilibrium.','Nonzero motor and load torques can balance.')], 'The source self-regulation claim is supported by its pictured slope ordering, not arbitrary load curves.',loc='Self-regulating assertion and descending-motor/ascending-load figure.',kind='figure',typ='derivation',diff='medium',steps=['Let δω be a small perturbation.','J δṡω ≈ [T_m′(ω*)−T_L′(ω*)] δω.','A negative coefficient divided by J>0 causes exponential decay.'],forms=[OP],assumptions=['Added scalar smooth rigid-shaft model without other dynamics.'],conflict='Self-regulation is stated generically; arbitrary torque-curve intersections need not have stable local slope.')
a(1711,'inertia-response','Acceleration after a disturbance','In a declared shaft model with J=0.02 kg m², motor torque is 0.80 N m and opposing load torque is 0.60 N m at the disturbed speed. What is angular acceleration?', [('10 rad/s².','Use the net 0.20 N m divided by inertia.'),('40 rad/s².','This ignores opposing load torque.'),('70 rad/s².','This adds rather than subtracts load torque.'),('−10 rad/s².','This reverses the specified net-torque sign.')], 'The source qualitative acceleration statement becomes a calculation only after inertia and torques are supplied.',loc='Motor torque exceeds load torque and acceleration sentence.',typ='numerical',steps=['α=(0.80−0.60)/0.02=10 rad/s².'],forms=[OP],assumptions=['Added rigid-shaft net-torque model; constant instantaneous values.'])
a(1712,'servo-system','Servo is a control system','Which combination matches the lecture’s position-servo summary?', [('Motor, position feedback such as an encoder, and a closed-loop position controller.','These are the three summarized elements.'),('Any unconnected motor and a printed accuracy label, without feedback or a controller.','A label does not supply the closed loop.'),('Only an encoder, with no actuator or control command.','A sensor alone does not generate motion.'),('Only a fixed-frequency power source, with no feedback or position reference.','That is not the summarized position-servo arrangement.')], 'Servo describes the controlled motion system, not a requirement for brushes or a particular field material.',loc='Servo Motor: DC/AC motor + encoder + closed-loop position controller.')
a(1712,'resolution-accuracy','Microstep command resolution','A 200-full-step motor uses eight microsteps per full step. What is its nominal command increment, and what does that establish?', [('0.225°; command resolution, not a guaranteed ±0.225° positioning accuracy.','Divide 1.8 degrees by eight, then distinguish resolution from accuracy.'),('0.225°; exactly that accuracy is guaranteed under any load.','Load and motor/drive errors still affect actual position.'),('14.4°; increasing microsteps makes each command larger.','This multiplies rather than divides the full-step angle.'),('1.8°; microstepping changes only the unit label.','It subdivides the nominal command increment.')], 'The numeric division is exact for commands; actual mechanics require separate accuracy assessment.',loc='Stepper 200 steps/rev and microstepping bullets.',typ='numerical',steps=['N_cmd=200×8=1600 commands/rev.','α_cmd=360/1600=0.225°.'],forms=[STEP],assumptions=['Added eight-way microstepping; nominal command mapping, no claim of achieved accuracy.'],external=['stepper'])
a(1712,'servo-accuracy','Possible precision is not a universal rating','The summary says positioning accuracy below 0.01° is possible. What can be concluded for an unspecified servo?', [('That level is an achievable example, not a guaranteed specification for every servo installation.','Actual accuracy depends on the selected system and conditions.'),('Every device called servo is guaranteed below 0.01° under every load.','Possible does not mean universal.'),('Encoder resolution alone equals final output-shaft accuracy even with backlash.','Resolution and system accuracy differ.'),('A closed-loop controller removes all calibration and mechanical error automatically.','Feedback does not eliminate every error source.')], 'Select from actual rated/measured performance rather than upgrading a possibility into a guarantee.',loc='High precision positioning, less-than-0.01-degree accuracy possible bullet.',typ='scenario')
a([1689,1712],'motor-prevalence','Context of DC and AC prevalence','How should the early DC-prevalence statement be reconciled with the summary’s industrial brushless-AC-servo claim?', [('Treat them as context-dependent source generalizations, not a universal exclusive ranking of motor use.','Application and era matter; both cannot be an unqualified exclusive rule.'),('Conclude that AC motors are absent from industrial robot joints.','The summary explicitly gives AC servos there.'),('Conclude that DC motors are never used for wheeled robots or conveyors.','The summary explicitly gives these DC examples.'),('Treat AC and DC as labels for the same power supply waveform in every drive.','Their drive conventions are not erased by the conflicting generalizations.')], 'Retain both claims and their scope instead of declaring either a universal market fact.',loc={1689:'DC motors mostly used in modern control statement.',1712:'DC application examples and brushless AC servos dominate industrial robotics bullet.'},conflict='Early unqualified DC prevalence and later industrial AC-servo prevalence have different unstated scopes.')
a(1712,'construction-control','Overlapping motor labels','Which pair of labels describes different classification axes rather than mutually exclusive motor families?', [('Coreless construction and servo closed-loop operation.','A coreless motor can be used in a servo system.'),('Zero current and nonzero current in the same conductor at the same instant.','These are mutually exclusive values under one definition, not motor-class axes.'),('A disconnected winding and the same winding energized in the same operating state.','Those are incompatible states, not the intended classification distinction.'),('Zero speed and nonzero speed at the same instant for one shaft.','These are different operating states, not overlapping design/control labels.')], 'The summary mixes physical construction, field/commutation type and control architecture; they should not all be treated as disjoint categories.',loc='DC types Brushed/Brushless/Coreless and separate Servo Motor definition.',typ='scenario')
a(1712,'application-choice','Bounded application match','Which pairing follows the summary without implying exclusive use?', [('Basic stepper positioning for a plotter; closed-loop servo axes for demanding robot-joint position control.','Both are source examples with different control requirements.'),('Unpowered encoder alone for conveyor drive; a tachogenerator alone for gripping torque.','Feedback devices do not replace actuators.'),('Squirrel-cage rotor bars as a software policy; PWM pulses as mechanical gear teeth.','This confuses electrical/mechanical and computational roles.'),('A continuous-rotation induction drive as proof that every application needs exactly 200 steps per revolution.','The 200-step example belongs to the stepper summary.')], 'These are representative applications, not restrictions that forbid other motor choices.',loc='Stepper printers/plotters/SCARA and servo robot-joint/CNC/pick-place application bullets.',typ='match')
