# Pre-freeze quality audit: replace weak distractors with specific nearby misconceptions.
def choices(n,opts):
 q=b.questions[n-1];shift=(n-1)%4;opts=opts[shift:]+opts[:shift];q['options']=[{'id':f'o{i+1}','text':v[0]} for i,v in enumerate(opts)];q['solution']['optionExplanations']={f'o{i+1}':v[1] for i,v in enumerate(opts)};q['correctOptionIds']=[f'o{(-shift)%4+1}'];q['solution']['misconceptions']=[v[1] for i,v in enumerate(opts) if f'o{i+1}' not in q['correctOptionIds']]
choices(12,[('Stationary carbon brushes contact rotating segmented commutator connections to the armature coils.','This is the source contact arrangement.'),('Rotating carbon brushes contact a stationary segmented commutator attached to the field frame.','This exchanges the moving and stationary contact components.'),('Stationary brushes contact two continuous slip rings that never switch the coil polarity.','Continuous slip rings do not perform the segmented reversal described.'),('The commutator switches the permanent-magnet polarity while the armature current stays fixed.','It switches electrical connections to the armature, not the permanent magnet polarity.')])
choices(13,[('The armature rotor.','They are labelled armature conductors.'),('The stator field-coil windings around each projecting pole.','Those surround the outer field poles, not the central cylinder slots.'),('The segmented commutator contact surfaces.','The label refers to active armature conductors, not the contact ring.'),('The carbon brush contact blocks.','Brushes are localized contacts, not the distributed slot conductors.')])
choices(14,[('Reverse armature current only, leaving field direction unchanged.','Exactly one sign changes.'),('Reverse both field and armature current.','Their product keeps its sign.'),('Double armature current without changing field direction.','Torque magnitude changes but its sign does not.'),('Halve the field magnitude while retaining both current and field directions.','Reducing a positive field magnitude does not reverse torque.')])
choices(17,[('V/(rad/s).','Multiplying by angular speed gives volts.'),('rpm/V.','That is a speed-per-voltage convention, inverse after unit conversion.'),('V/A.','That is resistance, relating current to a resistive voltage drop.'),('A/(rad/s).','That would relate angular speed to current rather than back EMF.')])
choices(23,[('600 A/s.','Initially RI and back EMF are zero, so V/L_a gives the slope.'),('6 A/s.','6 A is the eventual steady current, not the initial slope.'),('0 A/s.','Current is continuous, but its derivative need not be zero.'),('6000 A/s.','This corresponds to 2 mH rather than the specified 20 mH.')])
choices(27,[('Field and armature carry the same series current.','They share one current path.'),('Field and armature each receive the full supply across separate parallel branches.','That is the shunt connection.'),('Field current is fixed by a separate independent voltage source while armature current varies.','That describes separate excitation, not the shared series path.'),('Supply current splits between the field and armature and equals their sum.','That is the parallel-branch relation, not the series current relation.')])
choices(35,[('The prose calls compound starting torque highest, while the table labels it average.','Both descriptions occur on the same page.'),('Both prose and table label compound starting torque highest.','The table says average.'),('The prose calls compound starting torque average, while the table labels it highest.','This exchanges the two source entries.'),('Both prose and table label compound starting torque average.','The prose says highest.')])
choices(37,[('It combines a shunt field winding and a series field winding.','Both excitation paths are present.'),('It has only one field winding entirely in series with the armature.','That is the series-only arrangement.'),('It has only one field winding entirely in parallel with the armature.','That is the shunt-only arrangement.'),('Its field is supplied only by permanent magnets, with no field winding.','That is PM excitation rather than the stated compound winding.')])
choices(44,[('S1 with S4, versus S2 with S3.','These are the two opposite diagonals.'),('S1 with S3, versus S2 with S4.','These are same-leg rail-short paths.'),('S1 with S2, versus S3 with S4.','These connect both motor terminals toward the same rail rather than apply opposite polarities.'),('S1 with S4, versus S2 with S4.','The second pair is the right same-leg path, not a valid reverse diagonal.')])
choices(47,[('Selecting opposite diagonal drive paths and opposite rotation commands.','The complementary drive commands select reversal.'),('Selecting two same-leg paths to create the intended reversible motor voltage.','Same-leg paths short the supply rather than correctly drive the winding.'),('Selecting upper-device braking and lower-device braking, with no driven polarity change.','The source assigns complementary A/B states to the diagonal directional drives.'),('Selecting two encoder phase measurements from the shaft rather than issuing motor commands.','A/B in this drawing are transistor-drive control nodes.')])
choices(52,[('Stationary switched coils surround a permanent-magnet rotor; electronic switching replaces brush commutation.','The labels identify stator coils and PM rotor.'),('A mechanically commutated wound rotor rotates within stationary magnets.','That is the brushed PM arrangement rather than this BLDC diagram.'),('An unwound conducting cage rotor is supplied by induction from the stator.','That describes an induction cage rather than the shown PM rotor.'),('An unmagnetized toothed rotor aligns solely by reluctance with no PM poles.','That describes the later variable-reluctance construction, not the N/S rotor shown.')])
choices(54,[('Induction and synchronous.','Both phase branches divide into these two labels.'),('Series and shunt.','Those are wound-field DC connection categories.'),('Permanent-magnet and variable-reluctance stepper.','Those are the source stepper categories, not this tree.'),('Sensored and sensorless BLDC.','Those are commutation-feedback implementations, not these AC-tree leaves.')])
