# Add the explicit earlier equation premises where a later sketch alone is insufficient.
def cite(n,p,loc,kind='equation',role='premise'):
 q=b.questions[n-1]
 if not any(c['physicalPage']==p for c in q['citations']):
  q['citations'].append({'slideId':f'lectures-p{p:04d}','sourceId':'lectures','sourceSha256':SHA,'physicalPage':p,'kind':kind,'locator':f'Lecture L53, physical page {p}, printed footer {p-1684}: {loc}','evidenceText':(R/f'sources/text/lectures/page-{p:04d}.txt').read_text().strip(),'role':role,'region':None})
  c=b.concepts[q['conceptIds'][0]]
  if f'lectures-p{p:04d}' not in c['slideIds']:c['slideIds'].append(f'lectures-p{p:04d}')
